// SF-100: shared shipyard UI. Server inventory is the only source of saleable ships.
let allianceShipyardView=null;
const shipyardResources=['metal','crystal','eonium'];
function shipyardEsc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function shipyardNumber(value){const number=Number.isFinite(Number(value))?Number(value):0;return typeof nfmt==='function'?nfmt(number):String(number);}
function shipyardContext(){return {snapshot:state,player:state.centralPlayerId,generation:state.centralResetGeneration||0,resetEpoch:state.resetEpoch||0,alliance:state.alliance?.registryId||state.alliance?.name||''};}
function sameShipyardContext(previous){const current=shipyardContext();return previous.snapshot===current.snapshot&&previous.player===current.player&&previous.generation===current.generation&&previous.resetEpoch===current.resetEpoch&&previous.alliance===current.alliance;}
function shipyardCurrent(view){return allianceShipyardView===view&&sameShipyardContext(view.context)&&view.root.isConnected!==false;}
function shipyardCostText(cost){return shipyardResources.map(key=>shipyardNumber(Number(cost?.[key])||0)+' '+key).join(' · ');}
function shipyardInventoryRows(data){const rows=[];function add(planetId,shipId,value){const available=typeof value==='number'?value:Number(value?.availableAllianceShips??value?.available??value?.quantity??value?.qty);if(planetId&&shipId&&Number.isSafeInteger(available)&&available>0)rows.push({planetId:String(planetId),shipId:String(shipId),available});}function ledger(value,fallbackId){if(value?.planetId&&value.available&&typeof value.available==='object'){const member=(data.members||[]).find(m=>m.id===value.planetId);if(!member||(member.resetEpoch||0)!==(value.resetEpoch||0))return;for(const [shipId,n]of Object.entries(value.available))add(value.planetId,shipId,n);return;}if(Array.isArray(value)){for(const row of value)add(row.planetId??fallbackId,row.shipId??row.ship,row);}else if(value&&typeof value==='object')for(const [shipId,n]of Object.entries(value))add(fallbackId,shipId,n);}if(Array.isArray(data.inventory)){for(const row of data.inventory)row.available&&typeof row.available==='object'?ledger(row):add(row.planetId??row.memberId,row.shipId??row.ship,row);}else for(const [key,value]of Object.entries(data.inventory||{}))ledger(value,key);return rows.filter(row=>(data.members||[]).some(member=>member.id===row.planetId)&&(data.catalog||[]).some(ship=>ship.id===row.shipId));}
function availableAllianceShips(data,planetId,shipId){return shipyardInventoryRows(data).filter(row=>row.planetId===planetId&&row.shipId===shipId).reduce((sum,row)=>sum+row.available,0);}
function shipyardQuoteSignature(data){return JSON.stringify({generation:data.generation,revision:data.revision,fund:data.fund,factories:data.factories,catalog:data.catalog,members:(data.members||[]).map(member=>({id:member.id,race:member.race,resetEpoch:member.resetEpoch})),inventory:data.inventory});}
function shipyardProgress(order){const pools=Object.values(order.work||order.pools||order.factoryWork||{}),total=Number(order.total??order.totalWork??(pools.length?pools.reduce((sum,pool)=>sum+(Number(pool.total)||0),0):NaN)),remaining=Number(order.remaining??order.remainingWork??(pools.length?pools.reduce((sum,pool)=>sum+(Number(pool.remaining)||0),0):NaN));return Number.isFinite(total)&&total>0&&Number.isFinite(remaining)?Math.max(0,Math.min(100,Math.floor((1-remaining/total)*100))):null;}
function shipyardOrderRows(view){const data=view.data;return (data.orders||[]).map(order=>{const progress=shipyardProgress(order),finished=['complete','completed','delivered','cancelled','canceled','settled','escrow'].includes(String(order.status).toLowerCase()),items=(order.items||[]).map(item=>{const ship=data.catalog.find(s=>s.id===item.shipId),member=data.members.find(m=>m.id===item.planetId);return shipyardNumber(item.quantity??item.qty)+' '+shipyardEsc(ship?.name||item.shipId)+' → '+shipyardEsc(member?.name||item.planetId)+' / Fleet 4';}).join('<br>');return '<article class="shipyard-job"><div><b>'+shipyardEsc(order.name||'Order '+order.id)+'</b><p>'+items+'</p><small>'+shipyardEsc(order.status||'Pending')+(Number.isFinite(Number(order.ticksRemaining))?' · '+shipyardNumber(order.ticksRemaining)+' ticks remaining':'')+'</small>'+(progress===null?'':'<progress max="100" value="'+progress+'" aria-label="Order progress">'+progress+'%</progress><small>'+progress+'% complete</small>')+'</div>'+(!finished?'<button class="btn warn" type="button" data-shipyard-cancel-order="'+shipyardEsc(order.id)+'" '+(view.busy?'disabled':'')+'>CANCEL ORDER</button>':'')+'</article>';}).join('')||'<div class="empty">No alliance ship orders.</div>';}
function shipyardSalesRows(view){return (view.data.sales||[]).map(sale=>{const items=(sale.items||[{shipId:sale.shipId||sale.ship,quantity:sale.quantity??sale.qty,planetId:sale.planetId}]).map(item=>{const ship=view.data.catalog.find(s=>s.id===item.shipId),member=view.data.members.find(m=>m.id===item.planetId);return shipyardNumber(item.quantity??item.qty)+' '+shipyardEsc(ship?.name||item.shipId)+' · '+shipyardEsc(member?.name||item.planetId);}).join('<br>'),selling=String(sale.status).toLowerCase()==='selling';return '<article class="shipyard-job"><div><b>'+items+'</b><p>'+shipyardEsc(sale.status||'Pending sale')+'</p><small>'+((sale.dueTick??sale.returnTick)!==undefined?'Due tick '+shipyardEsc(sale.dueTick??sale.returnTick)+' · ':'')+shipyardCostText(sale.quote||sale.payout||{})+'</small></div>'+(selling?'<button class="btn" type="button" data-shipyard-cancel-sale="'+shipyardEsc(sale.id)+'" '+(view.busy?'disabled':'')+'>CANCEL SALE · 12-TICK RETURN</button>':'')+'</article>';}).join('')||'<div class="empty">No alliance ship sales.</div>';}
function paintAllianceShipyards(view){if(!shipyardCurrent(view))return;const data=view.data;if(!data){view.panel.innerHTML='<div class="ph"><div class="pt">ALLIANCE SHIPYARDS</div></div><p class="note">'+shipyardEsc(view.status||'Loading shared shipyard…')+'</p><button class="btn" data-shipyard-refresh type="button">RETRY</button>';return;}if(!data.members.some(member=>member.id===view.destination))view.destination=data.members[0]?.id||'';const races=[...new Set((data.members||[]).map(m=>m.race))].filter(race=>data.catalog.some(ship=>ship.race===race&&ship.canProduce!==false)),byRace=Object.fromEntries(races.map(race=>[race,data.catalog.filter(ship=>ship.race===race&&ship.canProduce!==false)])),rows=Array.from({length:Math.max(10,...Object.values(byRace).map(ships=>ships.length))},(_,index)=>'<tr><th scope="row">'+String(index+1).padStart(2,'0')+'</th>'+races.map(race=>{const ship=byRace[race][index];return ship?'<td><label for="shipyard-qty-'+shipyardEsc(ship.id)+'"><b>'+shipyardEsc(ship.name)+'</b><small>'+shipyardEsc(ship.class)+' · '+shipyardEsc(ship.factory)+'</small></label><input id="shipyard-qty-'+shipyardEsc(ship.id)+'" type="number" inputmode="numeric" min="0" max="20000" step="1" data-shipyard-quantity="'+shipyardEsc(ship.id)+'" value="'+shipyardEsc(view.quantities[ship.id]||'')+'" placeholder="0" aria-label="'+shipyardEsc(race+' '+ship.name+' quantity')+'" '+(view.busy?'disabled':'')+'><small>'+shipyardEsc(shipyardCostText(ship.cost))+'</small></td>':'<td class="dim">—</td>';}).join('')+'</tr>').join(''),inventory=shipyardInventoryRows(data),selectedMember=data.members.some(member=>member.id===view.saleMember)?view.saleMember:data.members[0]?.id||'',saleStocks=inventory.filter(row=>row.planetId===selectedMember),selectedShip=saleStocks.some(row=>row.shipId===view.saleShip)?view.saleShip:saleStocks[0]?.shipId||'';view.saleMember=selectedMember;view.saleShip=selectedShip;const counts=data.factories?.count,rates=data.factories?.rates,stat=value=>value&&typeof value==='object'?Object.entries(value).map(([key,n])=>shipyardEsc(key)+': '+shipyardNumber(n)).join(' · '):shipyardNumber(value||0);view.panel.innerHTML='<div class="ph"><div class="pt">ALLIANCE SHIPYARDS</div><button class="btn" data-shipyard-refresh type="button" '+(view.busy?'disabled':'')+'>REFRESH SHIPYARD</button></div><div class="shipyard-body"><div class="alliance-kpis"><div class="quick"><small>ALLIANCE FUND</small><strong>'+shipyardEsc(shipyardCostText(data.fund))+'</strong></div><div class="quick"><small>COMBINED FACTORIES</small><strong>'+stat(counts)+'</strong><span>'+stat(rates)+' PU / tick</span></div></div><p>Build the races represented by current members. All ordered ships arrive in the selected member’s existing Fleet 4.</p><label class="field" for="shipyard-destination">Destination member · Fleet 4</label><select id="shipyard-destination" data-shipyard-destination '+(view.busy?'disabled':'')+'>'+data.members.map(member=>'<option value="'+shipyardEsc(member.id)+'" '+(member.id===view.destination?'selected':'')+'>'+shipyardEsc(member.name)+' · '+shipyardEsc(member.race)+'</option>').join('')+'</select><div class="table-wrap shipyard-matrix"><table class="table"><thead><tr><th>#</th>'+races.map(race=>'<th scope="col">'+shipyardEsc(race)+'</th>').join('')+'</tr></thead><tbody>'+rows+'</tbody></table></div><p class="note" id="shipyard-order-quote"></p><button class="btn primary" type="button" data-shipyard-order '+(view.busy||view.uncertain||!data.members.length?'disabled':'')+'>CONFIRM SHARED ORDER</button><p class="shipyard-status" role="status" aria-live="polite">'+shipyardEsc(view.status||'')+'</p><section><h3>Orders and progress</h3>'+shipyardOrderRows(view)+'</section><section><h3>Sell alliance-produced ships</h3><p>Only available alliance-produced inventory can be sold. Sales return 50% after 12 ticks. Cancelled sales return ships after a further 12 ticks.</p><div class="controls"><div class="field"><label for="shipyard-sale-member">Member</label><select id="shipyard-sale-member" data-shipyard-sale-member '+(view.busy?'disabled':'')+'>'+data.members.map(member=>'<option value="'+shipyardEsc(member.id)+'" '+(member.id===selectedMember?'selected':'')+'>'+shipyardEsc(member.name)+'</option>').join('')+'</select></div><div class="field"><label for="shipyard-sale-ship">Alliance hull</label><select id="shipyard-sale-ship" data-shipyard-sale-ship '+(view.busy?'disabled':'')+'>'+saleStocks.map(row=>'<option value="'+shipyardEsc(row.shipId)+'" '+(row.shipId===selectedShip?'selected':'')+'>'+shipyardEsc(data.catalog.find(ship=>ship.id===row.shipId)?.name||row.shipId)+' · '+shipyardNumber(row.available)+' available</option>').join('')+(saleStocks.length?'':'<option value="">No available alliance ships</option>')+'</select></div><div class="field"><label for="shipyard-sale-quantity">Quantity</label><input id="shipyard-sale-quantity" data-shipyard-sale-quantity type="number" min="1" max="'+availableAllianceShips(data,selectedMember,selectedShip)+'" step="1" value="'+shipyardEsc(view.saleQuantity||1)+'" '+(view.busy?'disabled':'')+'></div><button class="btn" type="button" data-shipyard-sell '+(view.busy||view.uncertain||!saleStocks.length?'disabled':'')+'>CONFIRM 50% SALE</button></div><p class="note" id="shipyard-sale-quote"></p>'+shipyardSalesRows(view)+'</section></div>';updateShipyardQuotes(view);}
function updateShipyardQuotes(view){if(!shipyardCurrent(view)||!view.data)return;const bill={metal:0,crystal:0,eonium:0};let quantity=0,valid=true;for(const ship of view.data.catalog){const raw=view.quantities[ship.id];if(raw===''||raw===undefined)continue;const n=Number(raw);if(!Number.isSafeInteger(n)||n<0||n>20000){valid=false;continue;}quantity+=n;for(const key of shipyardResources)bill[key]+=(Number(ship.cost?.[key])||0)*n;}const quote=view.panel.querySelector('#shipyard-order-quote');if(quote)quote.textContent=valid?quantity+' ships · '+shipyardCostText(bill):'Use whole quantities from 0 to 20,000.';const sale=view.panel.querySelector('#shipyard-sale-quote'),ship=view.data.catalog.find(s=>s.id===view.saleShip),count=Number(view.saleQuantity)||0,available=availableAllianceShips(view.data,view.saleMember,view.saleShip);if(sale)sale.textContent=count>0&&Number.isSafeInteger(count)&&count<=available?'Available alliance ships: '+shipyardNumber(available)+' · Estimated 50% return: '+shipyardCostText(Object.fromEntries(shipyardResources.map(key=>[key,Math.floor((Number(ship?.cost?.[key])||0)*count*.5)])))+' · 12 ticks':'Choose a whole quantity within the available alliance inventory.';}
async function refreshAllianceShipyards(view,synchronise=true){if(view.loading)return;view.loading=true;const token=++view.token;try{if(typeof syncAllianceShips==='function'&&await syncAllianceShips()===false)throw Error('Reconcile Alliance Ships before using the shipyard.');if(synchronise&&typeof syncOwnedColony==='function'&&await syncOwnedColony(true)===false)throw Error('Synchronise your colony before refreshing the shared shipyard.');if(!shipyardCurrent(view))return;const data=await centralDirectoryRequest('/api/alliance-shipyards');if(!shipyardCurrent(view)||view.token!==token||data.generation!==view.context.generation)return;if(typeof syncAllianceShips==='function'&&await syncAllianceShips()===false)throw Error('Fleet 4 reconciliation is pending. Refresh the shipyard.');if(!shipyardCurrent(view))return;view.data=data;if(!data.members.some(member=>member.id===view.destination))view.destination=data.members[0]?.id||'';view.status='Shared shipyard refreshed.';view.uncertain=false;paintAllianceShipyards(view);}catch(error){if(shipyardCurrent(view)){view.status=error.message;paintAllianceShipyards(view);}}finally{view.loading=false;}}
async function submitAllianceShipyardAction(view,action,record){if(view.busy||view.loading||!view.data||view.uncertain)return;const context=view.context,old=view.data;let items=[];try{if(action==='order'){if(!old.members.some(member=>member.id===view.destination))throw Error('Choose a current destination member.');for(const [shipId,raw]of Object.entries(view.quantities)){if(raw===''||raw===undefined)continue;const quantity=Number(raw);if(!Number.isSafeInteger(quantity)||quantity<0||quantity>20000)throw Error('Use whole quantities from 0 to 20,000.');if(quantity){if(!old.catalog.some(ship=>ship.id===shipId))throw Error('A selected hull is no longer available.');items.push({shipId,quantity,planetId:view.destination});}}if(!items.length)throw Error('Enter at least one ship quantity.');}if(action==='sell'){const quantity=Number(view.saleQuantity);if(!Number.isSafeInteger(quantity)||quantity<1||quantity>availableAllianceShips(old,view.saleMember,view.saleShip))throw Error('Choose a whole quantity within the available alliance inventory.');items=[{shipId:view.saleShip,quantity,planetId:view.saleMember}];}}catch(error){view.status=error.message;paintAllianceShipyards(view);return;}view.busy=true;view.status='Checking current shared quote…';paintAllianceShipyards(view);let posted=false;try{if(typeof syncAllianceShips==='function'&&await syncAllianceShips()===false)throw Error('Reconcile Alliance Ships before confirming a shared order.');if(typeof syncOwnedColony==='function'&&await syncOwnedColony(true)===false)throw Error('Synchronise your colony before confirming this order.');if(!shipyardCurrent(view)||!sameShipyardContext(context))return;if(action==='sell'&&typeof syncAllianceFleetReadiness==='function')await syncAllianceFleetReadiness(true);const fresh=await centralDirectoryRequest('/api/alliance-shipyards');if(!shipyardCurrent(view)||fresh.generation!==context.generation)return;if(shipyardQuoteSignature(fresh)!==shipyardQuoteSignature(old)){view.data=fresh;throw Error('The shared quote changed. Review the updated fund, factories and inventory, then confirm again.');}const payload={id:crypto.randomUUID(),action,generation:fresh.generation,revision:fresh.revision,directoryRevision:fresh.directoryRevision,...(items.length?{items}:{}),...(action==='cancelOrder'?{orderId:record}:{}),...(action==='cancelSale'?{saleId:record}:{})};posted=true;const result=await centralDirectoryRequest('/api/alliance-shipyards',payload);if(!shipyardCurrent(view))return;if(typeof recordOrderConfirmation==='function')recordOrderConfirmation('alliance-shipyard-'+action,{id:result.order?.id||result.sale?.id||result.id||payload.id,items,orderId:payload.orderId,saleId:payload.saleId});if(action==='order')view.quantities={};if(typeof syncAllianceShips==='function'&&await syncAllianceShips()===false)throw Error('Action accepted; Fleet 4 reconciliation is pending.');if(!shipyardCurrent(view))return;view.status='Shared shipyard action accepted.';view.loading=false;await refreshAllianceShipyards(view,false);if(shipyardCurrent(view))view.status='Shared shipyard action accepted.';}catch(error){if(shipyardCurrent(view)){view.status=error.message+(posted&&!error.status?' Refresh the shipyard to verify the result before another order.':'');if(posted&&!error.status)view.uncertain=true;}}finally{view.busy=false;if(shipyardCurrent(view))paintAllianceShipyards(view);}}
function shipyardUIEvent(view,event){if(!shipyardCurrent(view))return;const target=event.target;if(target.dataset.shipyardQuantity!==undefined){view.quantities[target.dataset.shipyardQuantity]=target.value;updateShipyardQuotes(view);}if(target.hasAttribute('data-shipyard-destination'))view.destination=target.value;if(target.hasAttribute('data-shipyard-sale-quantity')){view.saleQuantity=target.value;updateShipyardQuotes(view);}if(target.hasAttribute('data-shipyard-sale-member')){view.saleMember=target.value;view.saleShip='';paintAllianceShipyards(view);}if(target.hasAttribute('data-shipyard-sale-ship')){view.saleShip=target.value;updateShipyardQuotes(view);}if(event.type!=='click')return;if(target.closest('[data-shipyard-refresh]'))void refreshAllianceShipyards(view);if(target.closest('[data-shipyard-order]'))void submitAllianceShipyardAction(view,'order');if(target.closest('[data-shipyard-sell]'))void submitAllianceShipyardAction(view,'sell');const cancel=target.closest('[data-shipyard-cancel-order]'),sale=target.closest('[data-shipyard-cancel-sale]');if(cancel)void submitAllianceShipyardAction(view,'cancelOrder',cancel.dataset.shipyardCancelOrder);if(sale)void submitAllianceShipyardAction(view,'cancelSale',sale.dataset.shipyardCancelSale);}
function renderAllianceShipyardsUI(root){if(!root)return;const context=shipyardContext();if(!context.player||!context.alliance||context.alliance==='Unaffiliated'){root.textContent='Join an alliance to use its shared shipyards.';return;}let view=allianceShipyardView;const previousRoot=view?.root;if(!view||!sameShipyardContext(view.context)){view=allianceShipyardView={root,context,data:null,quantities:{},destination:'',saleMember:'',saleShip:'',saleQuantity:1,status:'',busy:false,loading:false,uncertain:false,token:0,panel:null};}view.root=root;if(!view.panel||!root.contains(view.panel)){view.panel=document.createElement('section');view.panel.className='panel alliance-shipyards-ui';for(const type of ['click','input','change'])view.panel.addEventListener(type,event=>shipyardUIEvent(view,event));root.append(view.panel);paintAllianceShipyards(view);}const active=!root.closest||!!root.closest('#page-alliance.active');if(active&&!view.loading&&(!view.data||view.lastTick!==state.tick||previousRoot!==root)){view.lastTick=state.tick;void refreshAllianceShipyards(view);}}
